export { chainFocus, isValidUrl } from "./commands";
export { extensionPresent, nodeActive } from "./detection";
export { shallowEqual, useEditorState } from "./editor-state";
export { DEFAULT_EXTENSION_LABELS } from "./labels";
export type { ExtensionLabelKey, ExtensionLabels } from "./labels";
export { ToolbarProvider, useToolbar, useToolbarEditor } from "./context";
export type { ToolbarContextValue, ToolbarProviderProps } from "./context";
export type { ToolbarComponentProps } from "./types";

import type { ChainedCommands, Editor } from "@tiptap/core";

export const chainFocus = (editor: Editor): ChainedCommands =>
  editor.chain().focus();

export const isValidUrl = (url: string): boolean =>
  /^https?:\/\/\S+$/.test(url);

import type { Editor } from "@tiptap/core";
import type { ReactNode } from "react";
import { createContext, useContext, useMemo } from "react";

import type { ExtensionLabels } from "./labels";
import { DEFAULT_EXTENSION_LABELS } from "./labels";

export interface ToolbarContextValue {
  editor: Editor | null;
  labels: ExtensionLabels;
}

const ToolbarContext = createContext<ToolbarContextValue>({
  editor: null,
  labels: DEFAULT_EXTENSION_LABELS,
});

export interface ToolbarProviderProps {
  children: ReactNode;
  editor?: Editor | null;
  labels?: Partial<ExtensionLabels>;
}

export const ToolbarProvider = ({
  children,
  editor = null,
  labels,
}: ToolbarProviderProps) => {
  const value = useMemo(
    () => ({
      editor,
      labels: { ...DEFAULT_EXTENSION_LABELS, ...labels },
    }),
    [editor, labels]
  );

  return (
    <ToolbarContext.Provider value={value}>{children}</ToolbarContext.Provider>
  );
};

export const useToolbar = (): ToolbarContextValue => useContext(ToolbarContext);

export const useToolbarEditor = (
  editor: Editor | null | undefined
): Editor | null => {
  const context = useContext(ToolbarContext);
  return editor ?? context.editor ?? null;
};

import type { Editor } from "@tiptap/core";

export const extensionPresent = (
  editor: Editor | null,
  name: string
): boolean =>
  Boolean(
    editor &&
    !editor.isDestroyed &&
    editor.extensionManager.extensions.some(
      (extension) => extension.name === name
    )
  );

export const nodeActive = (
  editor: Editor | null,
  name: string,
  attributes?: Record<string, unknown>
): boolean =>
  Boolean(editor && !editor.isDestroyed && editor.isActive(name, attributes));

import type { Editor } from "@tiptap/core";
import { useCallback, useRef, useSyncExternalStore } from "react";

const defaultEqual = <T>(a: T, b: T): boolean => a === b;

export const shallowEqual = <T extends Record<string, unknown>>(
  a: T,
  b: T
): boolean => {
  if (a === b) {
    return true;
  }
  if (!a || !b) {
    return false;
  }
  const ak = Object.keys(a);
  const bk = Object.keys(b);
  if (ak.length !== bk.length) {
    return false;
  }
  return ak.every((k) => a[k] === b[k]);
};

const isPlainEmpty = <T>(value: T | undefined): value is undefined =>
  value === undefined;

export const useEditorState = <T>(
  editor: Editor | null,
  selector: (e: Editor) => T,
  isEqual: (a: T, b: T) => boolean = defaultEqual
): T | undefined => {
  const selectorRef = useRef(selector);
  const isEqualRef = useRef(isEqual);
  selectorRef.current = selector;
  isEqualRef.current = isEqual;

  const snapshotRef = useRef<{ value: T | undefined }>({
    value: editor ? selector(editor) : undefined,
  });

  const computeSnapshot = useCallback((): T | undefined => {
    if (!editor) {
      return undefined;
    }
    const next = selectorRef.current(editor);
    const current = snapshotRef.current.value;
    if (isPlainEmpty(current) || !isEqualRef.current(current, next)) {
      snapshotRef.current.value = next;
    }
    return snapshotRef.current.value;
  }, [editor]);

  const subscribe = useCallback(
    (onStoreChange: () => void) => {
      if (!editor) {
        return () => {
          /* Nothing to subscribe to. */
        };
      }
      const update = () => {
        computeSnapshot();
        onStoreChange();
      };
      editor.on("selectionUpdate", update);
      editor.on("transaction", update);
      return () => {
        editor.off("selectionUpdate", update);
        editor.off("transaction", update);
      };
    },
    [editor, computeSnapshot]
  );

  return useSyncExternalStore(subscribe, computeSnapshot, computeSnapshot);
};

export interface ExtensionLabels {
  addColumnLeft: string;
  addColumnRight: string;
  addRowAbove: string;
  addRowBelow: string;
  columnActions: string;
  columns: string;
  deleteColumn: string;
  deleteRow: string;
  deleteTable: string;
  headerRow: string;
  image: string;
  imagePlaceholder: string;
  insertTable: string;
  mergeCells: string;
  rowActions: string;
  rows: string;
  splitCell: string;
  tableActions: string;
}

export type ExtensionLabelKey = keyof ExtensionLabels;

export const DEFAULT_EXTENSION_LABELS: ExtensionLabels = {
  addColumnLeft: "Insert Left",
  addColumnRight: "Insert Right",
  addRowAbove: "Insert Above",
  addRowBelow: "Insert Below",
  columnActions: "Column actions",
  columns: "Columns",
  deleteColumn: "Delete column",
  deleteRow: "Delete row",
  deleteTable: "Delete table",
  headerRow: "Header row",
  image: "Image",
  imagePlaceholder: "Add an image",
  insertTable: "Insert table",
  mergeCells: "Merge cells",
  rowActions: "Row actions",
  rows: "Rows",
  splitCell: "Split cell",
  tableActions: "Table actions",
};

import type { Editor } from "@tiptap/core";

export interface ToolbarComponentProps {
  className?: string;
  editor?: Editor | null;
  size?: "icon" | "icon-lg" | "icon-sm";
}

import type { CommandProps } from "@tiptap/core";
import { Gapcursor } from "@tiptap/extension-gapcursor";
import { Table as TiptapTable } from "@tiptap/extension-table";
import { TableCell } from "@tiptap/extension-table-cell";
import { TableHeader } from "@tiptap/extension-table-header";
import { TableRow } from "@tiptap/extension-table-row";

export { TableToolbar } from "./toolbar";
export { TableHoverOverlay } from "./table-hover-overlay";

export interface TableConfigOptions {
  HTMLAttributes?: Record<string, unknown>;
  defaultCols?: number;
  defaultRows?: number;
  tableCellMinWidth?: number;
  withHeaderRow?: boolean;
  resizable?: boolean;
}

declare module "@tiptap/core" {
  interface Commands<ReturnType> {
    tableControl: {
      insertTableWithHeader: () => ReturnType;
      moveColumn: (from: number, to: number) => ReturnType;
      moveRow: (from: number, to: number) => ReturnType;
    };
  }
}

const clampIndex = (index: number, length: number): number =>
  Math.max(0, Math.min(index, length - 1));

const findTablePosition = (doc: {
  descendants: (
    cb: (node: { type: { name: string } }, pos: number) => boolean | undefined
  ) => void;
}): number => {
  let position = -1;
  doc.descendants((node, pos) => {
    if (position !== -1 || node.type.name !== "table") {
      return position === -1;
    }
    position = pos;
    return false;
  });
  return position;
};

export const Table = TiptapTable.extend<TableConfigOptions>({
  addCommands() {
    return {
      ...this.parent?.(),
      insertTableWithHeader:
        () =>
        ({ commands }: CommandProps) =>
          commands.insertTable({
            cols: this.options.defaultCols ?? 3,
            rows: this.options.defaultRows ?? 3,
            withHeaderRow: this.options.withHeaderRow ?? true,
          }),
      moveColumn:
        (from: number, to: number) =>
        ({ dispatch, state }: CommandProps) => {
          const tablePos = findTablePosition(state.doc);
          if (tablePos === -1 || from === to) {
            return false;
          }
          const table = state.doc.nodeAt(tablePos);
          if (!table) {
            return false;
          }

          const columnCount = table.child(0)?.childCount ?? 0;
          const source = clampIndex(from, columnCount);
          const target = clampIndex(to, columnCount);
          if (source === target) {
            return false;
          }

          const rows = [];
          for (let r = 0; r < table.childCount; r += 1) {
            const row = table.child(r);
            const cells = [];
            for (let c = 0; c < row.childCount; c += 1) {
              cells.push(row.child(c));
            }
            if (cells.length === 0 || source >= cells.length) {
              rows.push(row);
              continue;
            }
            const [moved] = cells.splice(source, 1);
            if (moved === undefined) {
              rows.push(row);
              continue;
            }
            const clampedTarget = Math.min(target, cells.length);
            cells.splice(clampedTarget, 0, moved);
            rows.push(row.type.create(row.attrs, cells));
          }

          const { tr } = state;
          tr.replaceWith(
            tablePos,
            tablePos + table.nodeSize,
            table.type.create(table.attrs, rows)
          );
          dispatch?.(tr);
          return true;
        },
      moveRow:
        (from: number, to: number) =>
        ({ dispatch, state }: CommandProps) => {
          const tablePos = findTablePosition(state.doc);
          if (tablePos === -1 || from === to) {
            return false;
          }
          const table = state.doc.nodeAt(tablePos);
          if (!table) {
            return false;
          }

          const source = clampIndex(from, table.childCount);
          const target = clampIndex(to, table.childCount);
          if (source === target) {
            return false;
          }

          const rows = [];
          for (let r = 0; r < table.childCount; r += 1) {
            rows.push(table.child(r));
          }
          const [moved] = rows.splice(source, 1);
          if (moved === undefined) {
            return false;
          }
          rows.splice(target, 0, moved);

          const { tr } = state;
          tr.replaceWith(
            tablePos,
            tablePos + table.nodeSize,
            table.type.create(table.attrs, rows)
          );
          dispatch?.(tr);
          return true;
        },
    };
  },
  addExtensions() {
    return [TableRow, TableCell, TableHeader, Gapcursor];
  },
  addOptions() {
    return {
      ...this.parent?.(),
      defaultCols: 3,
      defaultRows: 3,
      resizable: true,
      withHeaderRow: true,
    };
  },
});

"use client";
import { Button } from "@components/editor-ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@components/editor-ui/dropdown-menu";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@components/editor-ui/popover";
import type { ChainedCommands, Editor } from "@tiptap/core";
import { CheckIcon, Grid3x3 as GridIcon } from "lucide-react";
import { useRef, useState } from "react";

import { useToolbar, useToolbarEditor } from "../core/context";
import { extensionPresent } from "../core/detection";
import { shallowEqual, useEditorState } from "../core/editor-state";
import type { ToolbarComponentProps } from "../core/types";

const GRID_INIT_SIZE = 6;
const GRID_MAX_SIZE = 10;
const GRID_DEFAULT = { cols: 1, rows: 1 };

const createRange = (length: number) =>
  Array.from({ length }, (_, index) => index + 1);

const selectionInTable = (editor: Editor): boolean => {
  const { $head } = editor.state.selection;
  for (let { depth } = $head; depth > 0; depth -= 1) {
    if ($head.node(depth).type.spec.tableRole === "row") {
      return true;
    }
  }
  return false;
};

const findFirstCellPos = (editor: Editor): number => {
  let position = -1;
  editor.state.doc.descendants((node, nodePos) => {
    if (position !== -1) {
      return false;
    }
    if (node.type.name === "tableCell" || node.type.name === "tableHeader") {
      position = nodePos + 1;
      return false;
    }
    return true;
  });
  return position;
};

const run = (
  editor: Editor | null,
  operation: (chain: ChainedCommands) => ChainedCommands,
  disabled: boolean
) => {
  if (!editor || editor.isDestroyed || disabled) {
    return;
  }
  const chain = editor.chain().focus();
  if (!selectionInTable(editor)) {
    const position = findFirstCellPos(editor);
    if (position !== -1) {
      chain.setTextSelection(position);
    }
  }
  operation(chain).run();
};

export const TableToolbar = ({
  className,
  editor: editorProp,
}: ToolbarComponentProps) => {
  const { labels } = useToolbar();
  const editor = useToolbarEditor(editorProp);
  const [open, setOpen] = useState(false);
  const [gridSize, setGridSize] = useState({
    cols: GRID_INIT_SIZE,
    rows: GRID_INIT_SIZE,
  });
  const [selected, setSelected] = useState(GRID_DEFAULT);
  const selectedRef = useRef(GRID_DEFAULT);
  const activePointerId = useRef<number | null>(null);

  const state = useEditorState(
    editor,
    (edit) => ({
      canDeleteColumn: edit.can().deleteColumn(),
      canDeleteRow: edit.can().deleteRow(),
      canMerge: edit.can().mergeCells(),
      canSplit: edit.can().splitCell(),
      disabled: !extensionPresent(edit, "table"),
      headerOn: edit.isActive("tableHeader"),
      inTable: edit.isActive("table"),
    }),
    shallowEqual
  ) ?? {
    canDeleteColumn: false,
    canDeleteRow: false,
    canMerge: false,
    canSplit: false,
    disabled: true,
    headerOn: false,
    inTable: false,
  };

  const resetGrid = () => {
    setGridSize({ cols: GRID_INIT_SIZE, rows: GRID_INIT_SIZE });
    selectedRef.current = GRID_DEFAULT;
    setSelected(GRID_DEFAULT);
  };

  const selectGridSize = (rows: number, cols: number) => {
    if (rows === gridSize.rows && rows < GRID_MAX_SIZE) {
      setGridSize((prev) => ({ ...prev, rows: prev.rows + 1 }));
    }
    if (cols === gridSize.cols && cols < GRID_MAX_SIZE) {
      setGridSize((prev) => ({ ...prev, cols: prev.cols + 1 }));
    }
    const next = { cols, rows };
    selectedRef.current = next;
    setSelected(next);
  };

  const selectCell = (cell: HTMLElement): boolean => {
    const rows = Number(cell.dataset.rows);
    const cols = Number(cell.dataset.cols);
    if (Number.isNaN(rows) || Number.isNaN(cols)) {
      return false;
    }
    selectGridSize(rows, cols);
    return true;
  };

  const selectGridFromPointer = (
    event: React.PointerEvent<HTMLDivElement>
  ): boolean => {
    const cell =
      event.target instanceof Element &&
      event.target.closest<HTMLElement>("[data-table-grid-cell]");
    if (cell && event.currentTarget.contains(cell)) {
      return selectCell(cell);
    }
    const elementAtPointer = document.elementFromPoint(
      event.clientX,
      event.clientY
    );
    const fallback = elementAtPointer?.closest<HTMLElement>(
      "[data-table-grid-cell]"
    );
    return fallback ? selectCell(fallback) : false;
  };

  const onPointerDown = (event: React.PointerEvent<HTMLDivElement>) => {
    if (
      !event.isPrimary ||
      (event.pointerType === "mouse" && event.button !== 0)
    ) {
      return;
    }
    if (!selectGridFromPointer(event)) {
      return;
    }
    event.preventDefault();
    event.stopPropagation();
    activePointerId.current = event.pointerId;
    event.currentTarget.setPointerCapture(event.pointerId);
  };

  const onPointerMove = (event: React.PointerEvent<HTMLDivElement>) => {
    if (
      activePointerId.current !== null &&
      activePointerId.current !== event.pointerId
    ) {
      return;
    }
    if (activePointerId.current !== null) {
      event.preventDefault();
      event.stopPropagation();
    }
    selectGridFromPointer(event);
  };

  const onPointerUp = (event: React.PointerEvent<HTMLDivElement>) => {
    if (activePointerId.current !== event.pointerId) {
      return;
    }
    event.preventDefault();
    event.stopPropagation();
    selectGridFromPointer(event);
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
    activePointerId.current = null;
    const { rows, cols } = selectedRef.current;
    if (!editor || editor.isDestroyed || state.disabled) {
      return;
    }
    editor
      .chain()
      .focus()
      .insertTable({ cols, rows, withHeaderRow: true })
      .run();
    setOpen(false);
  };

  const onPointerCancel = (event: React.PointerEvent<HTMLDivElement>) => {
    if (activePointerId.current !== event.pointerId) {
      return;
    }
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
    activePointerId.current = null;
  };

  const onOpenChange = (next: boolean) => {
    setOpen(next);
    if (next) {
      resetGrid();
    }
  };

  const trigger = (
    <Button
      aria-label={labels.insertTable}
      className={className}
      disabled={state.disabled}
      size="icon-sm"
      title={labels.insertTable}
      variant={state.inTable ? "secondary" : "ghost"}
    >
      <GridIcon />
    </Button>
  );

  return state.inTable ? (
    <DropdownMenu open={open} onOpenChange={onOpenChange}>
      <DropdownMenuTrigger render={trigger} />
      <DropdownMenuContent align="start" side="bottom" sideOffset={6}>
        <DropdownMenuLabel>{labels.rows}</DropdownMenuLabel>
        <DropdownMenuItem
          onClick={() => run(editor, (c) => c.addRowBefore(), state.disabled)}
        >
          {labels.addRowAbove}
        </DropdownMenuItem>
        <DropdownMenuItem
          onClick={() => run(editor, (c) => c.addRowAfter(), state.disabled)}
        >
          {labels.addRowBelow}
        </DropdownMenuItem>
        <DropdownMenuItem
          disabled={!state.canDeleteRow}
          onClick={() => run(editor, (c) => c.deleteRow(), state.disabled)}
        >
          {labels.deleteRow}
        </DropdownMenuItem>
        <DropdownMenuSeparator />
        <DropdownMenuLabel>{labels.columns}</DropdownMenuLabel>
        <DropdownMenuItem
          onClick={() =>
            run(editor, (c) => c.addColumnBefore(), state.disabled)
          }
        >
          {labels.addColumnLeft}
        </DropdownMenuItem>
        <DropdownMenuItem
          onClick={() => run(editor, (c) => c.addColumnAfter(), state.disabled)}
        >
          {labels.addColumnRight}
        </DropdownMenuItem>
        <DropdownMenuItem
          disabled={!state.canDeleteColumn}
          onClick={() => run(editor, (c) => c.deleteColumn(), state.disabled)}
        >
          {labels.deleteColumn}
        </DropdownMenuItem>
        <DropdownMenuSeparator />
        <DropdownMenuItem
          onClick={() =>
            run(editor, (c) => c.toggleHeaderRow(), state.disabled)
          }
        >
          <span className="ext-table-toolbar-item-spacer">
            {labels.headerRow}
          </span>
          {state.headerOn ? <CheckIcon /> : null}
        </DropdownMenuItem>
        <DropdownMenuItem
          disabled={!state.canMerge}
          onClick={() => run(editor, (c) => c.mergeCells(), state.disabled)}
        >
          {labels.mergeCells}
        </DropdownMenuItem>
        <DropdownMenuItem
          disabled={!state.canSplit}
          onClick={() => run(editor, (c) => c.splitCell(), state.disabled)}
        >
          {labels.splitCell}
        </DropdownMenuItem>
        <DropdownMenuSeparator />
        <DropdownMenuItem
          variant="destructive"
          onClick={() => run(editor, (c) => c.deleteTable(), state.disabled)}
        >
          {labels.deleteTable}
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  ) : (
    <Popover onOpenChange={onOpenChange} open={open}>
      <PopoverTrigger render={trigger} />
      <PopoverContent
        align="start"
        className="ext-table-toolbar-popover"
        side="bottom"
        sideOffset={6}
      >
        <div className="ext-table-grid-popover">
          <div
            className="ext-table-grid ext-table-grid--picker"
            onPointerCancel={onPointerCancel}
            onPointerDown={onPointerDown}
            onPointerMove={onPointerMove}
            onPointerUp={onPointerUp}
            style={{ touchAction: "none" }}
          >
            {createRange(gridSize.rows).map((row) => (
              <div className="ext-table-grid-row" key={`table-row-${row}`}>
                {createRange(gridSize.cols).map((col) => (
                  <div
                    className={[
                      "ext-table-grid-cell",
                      col <= selected.cols &&
                        row <= selected.rows &&
                        "ext-table-grid-cell--selected",
                    ]
                      .filter(Boolean)
                      .join(" ")}
                    data-cols={col}
                    data-rows={row}
                    data-table-grid-cell
                    key={`table-col-${col}`}
                  />
                ))}
              </div>
            ))}
          </div>
          <div className="ext-table-grid-result">
            {selected.rows} x {selected.cols}
          </div>
        </div>
      </PopoverContent>
    </Popover>
  );
};

"use client";

import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@components/editor-ui/dropdown-menu";
import type { ChainedCommands } from "@tiptap/core";
import {
  MoreHorizontal,
  MoreVertical,
  Plus,
  Trash2,
  ArrowRight,
  ArrowLeft,
  ArrowUp,
  ArrowDown,
} from "lucide-react";
import { useCallback, useEffect, useRef, useState } from "react";

import { useToolbar, useToolbarEditor } from "../core/context";
import { extensionPresent } from "../core/detection";
import type { ExtensionLabels } from "../core/labels";
import type { ToolbarComponentProps } from "../core/types";

interface TableColumnLayout {
  center: number;
  left: number;
  width: number;
}

interface TableRowLayout {
  center: number;
  height: number;
  top: number;
}

interface TableRect {
  height: number;
  left: number;
  top: number;
  width: number;
}

interface ColumnControlProps {
  colCenter: number;
  labels: ExtensionLabels;
  menuOpen: boolean;
  onOpenChange: (open: boolean) => void;
  runColumnOp: (op: (c: ChainedCommands) => ChainedCommands) => void;
  tableRect: TableRect;
}

const ColumnControl = ({
  colCenter,
  labels,
  menuOpen,
  onOpenChange,
  runColumnOp,
  tableRect,
}: ColumnControlProps) => (
  <div
    className="ext-table-control ext-table-control--column"
    style={{
      left: colCenter,
      top: tableRect.top,
      transform: "translate(-50%, -50%)",
    }}
  >
    <DropdownMenu open={menuOpen} onOpenChange={onOpenChange}>
      <DropdownMenuTrigger
        render={
          <button
            type="button"
            aria-label={labels.columnActions}
            className="ext-table-grip"
            data-state={menuOpen ? "open" : "closed"}
          >
            <span
              className="ext-table-grip-stroke ext-table-grip-stroke--column"
              aria-hidden
            />
            <MoreHorizontal />
          </button>
        }
      />
      <DropdownMenuContent align="start" data-ext-floating side="bottom">
        <DropdownMenuItem
          onClick={() => runColumnOp((c) => c.addColumnBefore())}
        >
          <ArrowLeft />
          {labels.addColumnLeft}
        </DropdownMenuItem>
        <DropdownMenuItem
          onClick={() => runColumnOp((c) => c.addColumnAfter())}
        >
          <ArrowRight />
          {labels.addColumnRight}
        </DropdownMenuItem>
        <DropdownMenuSeparator />
        <DropdownMenuItem
          variant="destructive"
          onClick={() => runColumnOp((c) => c.deleteColumn())}
        >
          <Trash2 />
          {labels.deleteColumn}
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  </div>
);

interface RowControlProps {
  labels: ExtensionLabels;
  menuOpen: boolean;
  onOpenChange: (open: boolean) => void;
  rowCenter: number;
  runRowOp: (op: (c: ChainedCommands) => ChainedCommands) => void;
  tableRect: TableRect;
}

const RowControl = ({
  labels,
  menuOpen,
  onOpenChange,
  rowCenter,
  runRowOp,
  tableRect,
}: RowControlProps) => (
  <div
    className="ext-table-control ext-table-control--row"
    style={{
      left: tableRect.left,
      top: rowCenter,
      transform: "translate(-50%, -50%)",
    }}
  >
    <DropdownMenu open={menuOpen} onOpenChange={onOpenChange}>
      <DropdownMenuTrigger
        render={
          <button
            type="button"
            aria-label={labels.rowActions}
            className="ext-table-grip ext-table-grip--row"
            data-state={menuOpen ? "open" : "closed"}
          >
            <span
              className="ext-table-grip-stroke ext-table-grip-stroke--row"
